<template>
  <main class="contribution-page">
    <section class="contribution-wrap">
      <header class="hero glass">
        <div><span class="eyebrow">GROUP FUNDING</span><h1>Build the <em>Group Wallet.</em></h1><p>Payment is used here only when a member adds money to the shared Stokvel wallet. Group purchases are confirmed from the basket and never charge a member card.</p></div>
        <div class="wallet-orb"><span>AVAILABLE</span><strong>{{ money(walletBalance) }}</strong></div>
      </header>
      <div v-if="error" class="message error">{{ error }}</div><div v-if="success" class="message success">{{ success }}</div>
      <div v-if="loading" class="state glass">Loading contribution payment methods...</div>
      <div v-else class="layout">
        <section class="card glass"><span class="section-label">CONTRIBUTE TO {{ stokvelName || 'YOUR STOKVEL' }}</span><h2>Add money to the shared wallet.</h2><p class="muted">Your contribution becomes available to the whole group for catalogue purchases.</p>
          <label class="label">AMOUNT</label><div class="amount-input"><span>R</span><input v-model.number="amount" type="number" min="1" step="0.01" placeholder="0.00" /></div>
          <label class="label">PAYMENT METHOD</label><div class="cards"><label v-for="card in cards" :key="card.card_id" class="payment-method" :class="{selected:Number(selectedCard)===Number(card.card_id)}"><input v-model="selectedCard" type="radio" :value="card.card_id" /><span><strong>{{ card.card_type || 'Payment method' }}</strong><small>•••• {{ card.last_four_digits }} · Available {{ money(card.available_amount) }}</small></span></label></div>
          <button class="primary-btn" type="button" :disabled="saving||!selectedCard||!amount||Number(amount)<=0" @click="contribute">{{ saving?'Processing contribution…':`Add ${money(amount)} to Group Wallet` }}</button><p class="note">This payment funds the Group Wallet. It does not place an order.</p>
        </section>
        <aside class="side card glass"><span class="section-label">HOW STOCKWELL WORKS NOW</span><div class="step"><b>01</b><span><strong>Contribute</strong><small>Add money to the shared wallet.</small></span></div><div class="step"><b>02</b><span><strong>Vote</strong><small>Help the group decide what to buy.</small></span></div><div class="step"><b>03</b><span><strong>Shop</strong><small>Compare suppliers and build the group basket.</small></span></div><div class="step"><b>04</b><span><strong>Confirm</strong><small>Approve the basket and spend from the wallet.</small></span></div><div class="step"><b>05</b><span><strong>Track</strong><small>Follow the order through delivery.</small></span></div><button class="secondary-btn" type="button" @click="router.push('/member-dashboard')">Back to Group Hub</button></aside>
      </div>
    </section>
  </main>
</template>
<script setup>
import { onMounted, ref } from "vue";
import { useRouter } from "vue-router";
import { getPaymentOptions, payCurrentOrder } from "../services/api.js";
const router=useRouter(),loading=ref(true),saving=ref(false),error=ref(""),success=ref(""),cards=ref([]),selectedCard=ref(null),amount=ref(null),walletBalance=ref(0),stokvelName=ref("");
function money(value){return `R ${Number(value||0).toLocaleString('en-ZA',{minimumFractionDigits:2,maximumFractionDigits:2})}`}
async function load(){loading.value=true;error.value="";try{const response=await getPaymentOptions();cards.value=response.cards||[];walletBalance.value=Number(response.wallet?.available_balance||0);stokvelName.value=response.stokvel?.stokvel_name||"";selectedCard.value=cards.value[0]?.card_id||null}catch(err){error.value=err.response?.data?.message||"Unable to load contribution payment methods."}finally{loading.value=false}}
async function contribute(){if(saving.value||!selectedCard.value||Number(amount.value)<=0)return;saving.value=true;error.value="";success.value="";try{const response=await payCurrentOrder({card_id:selectedCard.value,amount:Number(amount.value)});walletBalance.value=Number(response.contribution?.wallet_balance??walletBalance.value+Number(amount.value));success.value=`${money(amount.value)} was added to the Group Wallet.`;amount.value=null}catch(err){error.value=err.response?.data?.message||"Contribution could not be completed."}finally{saving.value=false}}
onMounted(load);
</script>
<style scoped>
.contribution-page{min-height:100vh;background:var(--sw-page-background);color:var(--sw-page-text)}.contribution-wrap{width:min(1120px,calc(100% - 32px));margin:auto;padding:40px 0 80px}.glass{background:var(--sw-glass-light);border:1px solid var(--sw-glass-light-border);box-shadow:var(--sw-glass-shadow-light);backdrop-filter:blur(var(--sw-glass-blur));border-radius:24px}.hero{min-height:280px;padding:42px;display:flex;align-items:center;justify-content:space-between;gap:30px;background:var(--sw-page-gradient)}.eyebrow,.section-label{color:var(--sw-gold-500);font:800 10px var(--sw-font-body);letter-spacing:.14em}.hero h1{margin:18px 0 14px;font:800 clamp(44px,7vw,72px)/.9 var(--sw-font-heading);letter-spacing:-.06em}.hero h1 em{font-style:normal;color:var(--sw-gold-500)}.hero p{max-width:650px;color:var(--sw-page-text-soft);line-height:1.7}.wallet-orb{width:190px;height:190px;flex:0 0 190px;border:1px solid var(--sw-gold-500);border-radius:50%;display:grid;place-items:center;align-content:center;gap:8px;text-align:center}.wallet-orb span{font:800 9px var(--sw-font-body);letter-spacing:.12em;color:var(--sw-page-text-soft)}.wallet-orb strong{font:800 23px var(--sw-font-heading);color:var(--sw-gold-500)}.message{margin-top:16px;padding:14px 17px;border-radius:14px;font:11px var(--sw-font-body)}.message.error{border:1px solid rgba(210,75,55,.35);color:#b42318;background:rgba(210,75,55,.08)}.message.success{border:1px solid rgba(55,170,105,.35);color:#247747;background:rgba(55,170,105,.08)}.state{margin-top:18px;padding:50px;text-align:center}.layout{display:grid;grid-template-columns:1.15fr .85fr;gap:18px;margin-top:18px}.card{padding:28px}.card h2{margin:10px 0 7px;font:800 28px var(--sw-font-heading)}.muted,.note{color:var(--sw-page-text-soft);font:11px/1.6 var(--sw-font-body)}.label{display:block;margin-top:24px;margin-bottom:8px;color:var(--sw-page-text-soft);font:800 9px var(--sw-font-body);letter-spacing:.12em}.amount-input{display:flex;align-items:center;gap:8px;padding:4px 15px;border:1px solid var(--sw-input-border);border-radius:14px;background:var(--sw-page-background)}.amount-input span{font-weight:800;color:var(--sw-gold-500)}.amount-input input{width:100%;border:0;outline:0;padding:12px 4px;background:transparent;color:var(--sw-page-text);font-size:18px}.cards{display:grid;gap:10px}.payment-method{display:flex;align-items:center;gap:13px;padding:15px;border:1px solid var(--sw-input-border);border-radius:14px;background:var(--sw-page-surface);cursor:pointer}.payment-method.selected{border-color:var(--sw-gold-500);box-shadow:0 0 0 2px color-mix(in srgb,var(--sw-gold-500) 15%,transparent)}.payment-method input{accent-color:var(--sw-gold-500)}.payment-method span{display:grid;gap:4px}.payment-method small{color:var(--sw-page-text-soft)}.primary-btn,.secondary-btn{margin-top:22px;width:100%;padding:14px 17px;border-radius:12px;font:800 10px var(--sw-font-body);cursor:pointer}.primary-btn{border:0;background:var(--sw-gold-500);color:var(--sw-purple-900)}.primary-btn:disabled{opacity:.5;cursor:not-allowed}.secondary-btn{border:1px solid var(--sw-input-border);background:transparent;color:var(--sw-page-text)}.step{display:flex;gap:13px;padding:17px 0;border-bottom:1px solid var(--sw-input-border)}.step>b{color:var(--sw-gold-500);font:800 10px var(--sw-font-body)}.step span{display:grid;gap:4px}.step small{color:var(--sw-page-text-soft);font:10px/1.5 var(--sw-font-body)}.note{margin:12px 0 0;text-align:center}@media(max-width:800px){.hero{padding:30px;flex-direction:column;align-items:flex-start}.wallet-orb{align-self:center}.layout{grid-template-columns:1fr}}@media(max-width:520px){.contribution-wrap{width:min(100% - 22px,1120px)}.hero,.card{padding:23px}}
</style>
